# ===== WEEK 2 =====
n=5
cover("1130_s1","CODING 101","ICD-10 vs CPT vs HCPCS","The 3 code sets every claim speaks",1,n)
single("1201","BENCHMARK","Clean claim rate","The share of claims paid on first submission, with no edits or rework. Many practices aim for 95% or higher. Every point below that is rework your team pays for.")
n=6
cover("1202_s1","PAYMENT POSTING","How to read an EOB in 60 seconds","5 fields to check first",1,n)
code("1202_s2","Billed","What the practice charged","Rarely what you get paid. Don't judge a payment against this number.",2,n)
code("1202_s3","Allowed","The payer's approved amount for the service","Compare it to the contracted rate. Underpayments hide here.",3,n)
code("1202_s4","Paid","What the payer actually paid","Allowed minus patient responsibility should equal paid. If not, dig in.",4,n)
code("1202_s5","CARC/RARC","The adjustment and remark codes","They tell you why the amount changed and what to do next.",5,n)
cta("1202_s6","Patient responsibility is the last field.","Deductible, copay, coinsurance: bill it promptly.\nSave this for posting day.",6,n)
cards("1203","CAREERS IN RCM","A day in the life of an AR caller",[("Morning","Pull the worklist by age and dollar value."),("Midday","Check payer portals, call payers, fix and resubmit."),("Afternoon","Document every action. Escalate what's stuck.")],"Persistence pays practices.")
n=5
cover("1204_s1","PRIOR AUTH","Prior authorization: 5 rules that save claims","Get it before, not after",1,n)
bullets("1204_s2","Know when it's needed",["Check the payer's prior auth list for every new order","Lists change, so check every time","Imaging, infusions and specialty drugs are common triggers"],2,n)
bullets("1204_s3","Get it right",["Match CPT and ICD-10 codes exactly to what will be billed","Note the auth number, approved units and date range","Submit clinical notes that support medical necessity"],3,n)
bullets("1204_s4","Keep it valid",["Track expiry dates and visit counts","Re-authorize before the last approved visit","An auth isn't a payment guarantee: eligibility still matters"],4,n)
cta("1204_s5","No auth, no payment.","Share this with your front desk.\nFollow @rcm.axis",5,n)
single("1205","DOCUMENTATION TIP","Document why, not just what.","Payers pay for medical necessity. A note that explains the reason for the service survives audits and appeals.")
single("1206","WHAT WE VALUE","What makes a great RCM professional?","Curiosity about why a claim was denied. Ownership of the outcome. Clean documentation. Patience on hold.",dark=True)
n=7
cover("1209_s1","CODING 101","5 modifiers every coder should know","Two characters that change the payment",1,n)
code("1209_s2","25","Significant, separately identifiable E/M on the same day as a procedure","The note must show the visit stood on its own.",2,n)
code("1209_s3","59","Distinct procedural service","Use only when no more specific modifier (XE, XS, XP, XU) fits.",3,n)
code("1209_s4","26","Professional component","The physician's interpretation, billed apart from the equipment.",4,n)
code("1209_s5","TC","Technical component","The equipment, staff and supplies side of the service.",5,n)
code("1209_s6","50","Bilateral procedure","Performed on both sides in the same session. Check payer billing rules.",6,n)
cta("1209_s7","Wrong modifier, wrong payment.","Save this for your next coding audit.\nFollow @rcm.axis",7,n)
cards("1210","CAREERS IN RCM","CPC or CCS?",[("CPC (AAPC)","Physician and outpatient coding. Common entry point for practice coding roles."),("CCS (AHIMA)","Hospital and inpatient coding. Deeper focus on facility coding.")],"Pick the setting you want to work in.")
n=6
cover("1211_s1","APPEALS","Appeals that win","A 5-part structure",1,n)
steps("1211_s2","Open strong",[("1","Claim details","Patient, DOS, claim number, billed amount."),("2","Denial reason","Quote the exact CARC/RARC and date.")],2,n)
steps("1211_s3","Make the case",[("3","Why it's wrong","Cite the payer policy, contract or coding rule."),("4","Evidence","Attach notes, auth, proof of timely filing.")],3,n)
steps("1211_s4","Close clearly",[("5","The ask","State exactly what you want: reprocess and pay.")],4,n)
bullets("1211_s5","Before you send",["Check the appeal deadline","Use the payer's form if required","Track the appeal and follow up"],5,n)
cta("1211_s6","A denial is a question. An appeal is the answer.","Follow @rcm.axis",6,n)
single("1212","AR TIP","Read the remark code, not just the denial code.","The CARC says what happened. The RARC usually says what to fix.")
single("1213","ABOUT RCMAXIS","Specialty RCM is different.","Behavioral health, ABA, neurology and other specialties each bring their own payer rules. That's where we focus.",dark=True)
n=5
cover("1214_s1","CREDENTIALING","Credentialing vs. enrollment vs. contracting","3 steps people mix up",1,n)
bullets("1214_s2","Credentialing",["Verifies the provider's qualifications","License, education, board certification, history"],2,n)
bullets("1214_s3","Enrollment",["Registers the provider with the payer to bill","Assigns effective dates and IDs"],3,n)
bullets("1214_s4","Contracting",["Sets the rates and terms the payer will pay","Negotiable for many commercial payers"],4,n)
cta("1214_s5","All three must be done before you bill.","Follow @rcm.axis for credentialing basics.",5,n)
single("1215","BENCHMARK","Days in AR","How long, on average, it takes to get paid. Many practices aim to stay under 40 days. Rising days in AR is an early warning sign.")
n=6
cover("1216_s1","FRONT DESK","5 ways to collect more at the front desk","Patient balances start at check-in",1,n)
bullets("1216_s2","Before the visit",["Verify eligibility and benefits","Give patients a cost estimate"],2,n)
bullets("1216_s3","At check-in",["Collect copays every time","Ask for prior balances politely"],3,n)
bullets("1216_s4","After the visit",["Send clear, simple statements","Offer payment plans for larger balances"],4,n)
bullets("1216_s5","Make it easy",["Accept cards and online payments","Store a card on file with the patient's consent"],5,n)
cta("1216_s6","Easy to pay means more paid.","Share this with your front desk.\nFollow @rcm.axis",6,n)
cards("1217","CAREERS IN RCM","Your path into US RCM",[("Start","Learn medical terminology and payer basics."),("Build","Charge entry, payment posting, AR calling."),("Grow","Earn a certification like CPC. Specialize in denials, coding or credentialing.")],"Every expert started at step one.")
n=6
cover("1218_s1","YEAR-END","January checklist for US practices","What changes on January 1",1,n)
bullets("1218_s2","Patients",["Deductibles reset for most plans","Re-verify every patient's insurance at the first visit"],2,n)
bullets("1218_s3","Codes",["New and revised CPT codes take effect","Update charge masters and templates"],3,n)
bullets("1218_s4","Rates",["New Medicare fee schedule applies","Check commercial fee schedule updates"],4,n)
bullets("1218_s5","Providers",["Check upcoming credentialing renewals","Keep CAQH profiles current"],5,n)
cta("1218_s6","A clean January starts in December.","Save this checklist.\nFollow @rcm.axis",6,n)
single("1219","AR TIP","Check the payer portal before you call.","Claim status, EOBs and denial details are often already there. Call when the portal can't answer.")
single("1220","FOLLOW ALONG","Want to build a career in US RCM?","Learn with us here. We're building a global team for US specialty practices, and opportunities will be posted here first.",dark=True)
